931|static unsigned long
932|generate_hash_secret_salt(XML_Parser parser) {
933|  unsigned long entropy;
934|  (void)parser;
935|
936|  /* "Failproof" high quality providers: */
937|#if defined(HAVE_ARC4RANDOM_BUF)
938|  arc4random_buf(&entropy, sizeof(entropy));
939|  return ENTROPY_DEBUG("arc4random_buf", entropy);
940|#elif defined(HAVE_ARC4RANDOM)
941|  writeRandomBytes_arc4random((void *)&entropy, sizeof(entropy));
942|  return ENTROPY_DEBUG("arc4random", entropy);
943|#else
944|  /* Try high quality providers first .. */
945|#  ifdef _WIN32
946|  if (writeRandomBytes_rand_s((void *)&entropy, sizeof(entropy))) {
947|    return ENTROPY_DEBUG("rand_s", entropy);
948|  }
949|#  elif defined(HAVE_GETRANDOM) || defined(HAVE_SYSCALL_GETRANDOM)
950|  if (writeRandomBytes_getrandom_nonblock((void *)&entropy, sizeof(entropy))) {
951|    return ENTROPY_DEBUG("getrandom", entropy);
952|  }
953|#  endif
954|#  if ! defined(_WIN32) && defined(XML_DEV_URANDOM)
955|  if (writeRandomBytes_dev_urandom((void *)&entropy, sizeof(entropy))) {
956|    return ENTROPY_DEBUG("/dev/urandom", entropy);
957|  }
958|#  endif /* ! defined(_WIN32) && defined(XML_DEV_URANDOM) */
959|  /* .. and self-made low quality for backup: */
960|
961|  /* Process ID is 0 bits entropy if attacker has local access */
962|  entropy = gather_time_entropy() ^ getpid();
963|
964|  /* Factors are 2^31-1 and 2^61-1 (Mersenne primes M31 and M61) */
965|  if (sizeof(unsigned long) == 4) {
966|    return ENTROPY_DEBUG("fallback(4)", entropy * 2147483647);
967|  } else {
968|    return ENTROPY_DEBUG("fallback(8)",
969|                         entropy * (unsigned long)2305843009213693951ULL);
970|  }
971|#endif
972|}

