990|static enum XML_Error
991|callProcessor(XML_Parser parser, const char *start, const char *end,
992|              const char **endPtr) {
993|  const size_t have_now = EXPAT_SAFE_PTR_DIFF(end, start);
994|
995|  if (parser->m_reparseDeferralEnabled
996|      && ! parser->m_parsingStatus.finalBuffer) {
997|    // Heuristic: don't try to parse a partial token again until the amount of
998|    // available data has increased significantly.
999|    const size_t had_before = parser->m_partialTokenBytesBefore;
1000|    // ...but *do* try anyway if we're close to causing a reallocation.
1001|    size_t available_buffer
1002|        = EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer);
1003|#if XML_CONTEXT_BYTES > 0
1004|    available_buffer -= EXPAT_MIN(available_buffer, XML_CONTEXT_BYTES);
1005|#endif
1006|    available_buffer
1007|        += EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd);
1008|    // m_lastBufferRequestSize is never assigned a value < 0, so the cast is ok
1009|    const bool enough
1010|        = (have_now >= 2 * had_before)
1011|          || ((size_t)parser->m_lastBufferRequestSize > available_buffer);
1012|
1013|    if (! enough) {
1014|      *endPtr = start; // callers may expect this to be set
1015|      return XML_ERROR_NONE;
1016|    }
1017|  }
1018|  g_parseAttempts += 1;
1019|  const enum XML_Error ret = parser->m_processor(parser, start, end, endPtr);
1020|  if (ret == XML_ERROR_NONE) {
1021|    // if we consumed nothing, remember what we had on this parse attempt.
1022|    if (*endPtr == start) {
1023|      parser->m_partialTokenBytesBefore = have_now;
1024|    } else {
1025|      parser->m_partialTokenBytesBefore = 0;
1026|    }
1027|  }
1028|  return ret;
1029|}

